{"content": "from pydantic import Field
from pydantic_settings import BaseSettings, SettingsConfigDict


class Settings(BaseSettings):
    model_config = SettingsConfigDict(env_prefix="INVENTORY_", populate_by_name=True)

    app_name: str = "inventory"
    debug: bool = False
    # v1 `env=` became `validation_alias=`. In pydantic-settings an explicit alias
    # bypasses env_prefix, so this still reads INVENTORY_DB_URL.
    database_url: str = Field("sqlite:///local.db", validation_alias="INVENTORY_DB_URL")
    max_connections: int = 10


def load_settings() -> Settings:
    return Settings()
"}
